   7 /**
   8  * A simple hook to detect if the current viewport is mobile-sized.
   9  * @returns A boolean indicating if the screen is mobile-sized.
  10  */
  11 export function useMobile(): boolean {
  12     const [isMobile, setIsMobile] = useState(false);
  13 
  14     useEffect(() => {
  15         // This function will only run on the client side
  16         const checkScreenSize = () => {
  17             setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
