  22 
  23         // Add event listener for window resize
  24         window.addEventListener('resize', checkScreenSize);
  25 
  26         // Cleanup listener on component unmount
  27         return () => {
  28             window.removeEventListener('resize', checkScreenSize);
  29         };
  30     }, []);
  31 
  32     return isMobile;
  33 }
